class Library:
    def __init__(self):
        self._books = {}
        self._history = {}

    def add_book(self, isbn: str, copies: int = 1) -> None:
        if not isbn:
            raise ValueError("ISBN cannot be empty")
        if not isinstance(copies, int) or copies <= 0:
            raise ValueError("Copies must be a positive integer")
        if isbn not in self._books:
            self._books[isbn] = {'copies': 0, 'loans': [], 'history': []}
        self._books[isbn]['copies'] += copies

    def check_out(self, isbn: str, borrower: str) -> None:
        if not borrower:
            raise ValueError("Borrower ID cannot be empty")
        if isbn not in self._books:
            raise KeyError("ISBN not in catalog")
        if self._books[isbn]['copies'] == 0:
            raise NoCopyAvailable("No copy available")
        self._books[isbn]['copies'] -= 1
        self._books[isbn]['loans'].append(borrower)
        self._books[isbn]['history'].append(('check_out', borrower))

    def return_book(self, isbn: str, borrower: str) -> None:
        if not borrower:
            raise ValueError("Borrower ID cannot be empty")
        if isbn not in self._books:
            raise KeyError("ISBN not in catalog")
        if borrower not in self._books[isbn]['loans']:
            raise LibraryError("Borrower has no copy checked out")
        self._books[isbn]['copies'] += 1
        self._books[isbn]['loans'].remove(borrower)
        self._books[isbn]['history'].append(('return', borrower))

    def get_available(self, isbn: str) -> int:
        if isbn not in self._books:
            raise KeyError("ISBN not in catalog")
        return self._books[isbn]['copies']

    def get_loans(self, borrower: str) -> list[str]:
        if not borrower:
            raise ValueError("Borrower ID cannot be empty")
        return [isbn for isbn, data in self._books.items() if borrower in data['loans']]

    def get_history(self, isbn: str) -> list[tuple[str, str]]:
        if isbn not in self._books:
            raise KeyError("ISBN not in catalog")
        return self._books[isbn]['history']

    def get_books(self) -> list[str]:
        return list(self._books.keys())
